-- Главная по ТЗ (тренажёр ЕГЭ с ИИ): новые тексты hero / capabilities / process / faq и заголовок + описание страницы.
--
-- Тексты главной читаются из content_blocks и перекрывают docker/api/content/landing.json, поэтому одной правкой JSON
-- они на сайте не появятся. Блоки меняются ТОЛЬКО если лежат в исходном засеянном виде (по md5): если кто-то уже
-- отредактировал их в админке, миграция их не трогает (тогда новые вопросы и текст шага добавьте там же).
-- Заголовок и описание главной (seo) заменяются всегда: так велит ТЗ.
-- Откат: supabase/rollback/0046_home_rework_down.sql (+ git checkout тега pre-home-rework).
update public.content_blocks
   set data = $j${"title":"Подготовка к ЕГЭ с ИИ-репетитором, который объясняет, а не решает за тебя","highlight":"ИИ-репетитором","subtitle":"Онлайн-тренажёр ЕГЭ: задания ФИПИ, диагностика уровня, персональный план и проверка сочинений. Начать можно бесплатно."}$j$::jsonb, updated_at = now()
 where key = 'hero'
   and md5(data::text) = '796375b06b3c193a7cba6c937bfb2d50';

update public.content_blocks
   set data = $j$[{"icon":"target","t":"Диагностика уровня","d":"8–12 заданий — и понятно, с чего начинать."},{"icon":"book","t":"Персональный план","d":"Что повторить сегодня, сколько тренироваться на неделе."},{"icon":"list","t":"Задания формата ЕГЭ","d":"Открытый банк ФИПИ, мгновенная проверка по эталону."},{"icon":"chat","t":"ИИ-объяснения без готовых ответов","d":"Наводит на решение вопросами, а не выдаёт результат."},{"icon":"check","t":"Проверка сочинений и развёрнутых ответов","d":"По критериям, с чёткими баллами по каждому пункту."},{"icon":"list","t":"Тетрадь ошибок","d":"Ошибки попадают в тетрадь, ИИ помогает с разбором ошибок, а сами задания возвращаются на повторение по графику."},{"icon":"timer","t":"Пробные варианты","d":"Таймер, часть 1 и часть 2 — как на настоящем экзамене."}]$j$::jsonb, updated_at = now()
 where key = 'capabilities'
   and md5(data::text) = '95e341677b65c14a0c3938109c7dec05';

update public.content_blocks
   set data = $j$[{"n":"01","icon":"target","t":"Диагностика","d":"8–12 заданий по предмету, 7–10 минут, без подсказок. В конце ты видишь свой уровень, сильные и слабые темы и ориентировочный балл."},{"n":"02","icon":"book","t":"Персональный план","d":"На основе результатов — что повторить сегодня, сколько тренировок на неделе и когда пробник."},{"n":"03","icon":"chat","t":"Тренировки с ИИ","d":"Решаешь задания ФИПИ, при затруднении — уровневые подсказки и объяснение темы, без готового ответа."},{"n":"04","icon":"timer","t":"Пробный вариант","d":"Часть 1 и часть 2 на время, без подсказок — как на настоящем экзамене. Разбор после сдачи."}]$j$::jsonb, updated_at = now()
 where key = 'process'
   and md5(data::text) = '10ef5108bc581df487c0122a84deaa76';

update public.content_blocks
   set data = $j$[{"q":"Это официальный ресурс ФИПИ?","a":"Нет. Это учебный проект, который ориентируется на формат Открытого банка заданий ФИПИ и демоверсии ЕГЭ, но не является официальным ресурсом ФИПИ или Рособрнадзора."},{"q":"ИИ даст готовый ответ, если попросить?","a":"Нет, по конструкции. Даже если явно попросить — ИИ объяснит тему, задаст наводящий вопрос или разберёт похожий пример, но не назовёт финальный ответ твоего задания."},{"q":"Нужно заниматься каждый день?","a":"Нет. На онбординге ты сам выбираешь темп — от 10 минут до часа в день, план подстраивается под это время."},{"q":"Прогресс сохранится, если я закрою вкладку?","a":"Да, после регистрации план, диагностика и история попыток сохраняются в твоём аккаунте и доступны при следующем входе."},{"q":"Можно ли пользоваться ЕГЭ·ПРО бесплатно?","a":"Да. Бесплатный тариф включает 2 предмета на выбор, до 3 обращений к ИИ-репетитору в день, диагностику, персональный план и пробные варианты."},{"q":"Чем ЕГЭ·ПРО отличается от ChatGPT?","a":"ИИ-репетитор в ЕГЭ·ПРО не называет финальный ответ задания, а ведёт к нему подсказками. Задания берутся в формате Открытого банка ФИПИ, а диагностика, план, тетрадь ошибок и пробные варианты складываются в путь подготовки, который сохраняется в аккаунте. Универсальный чат-бот обычно просто решает задачу."},{"q":"Откуда задания?","a":"Задания составлены в формате Открытого банка заданий ФИПИ и демоверсий ЕГЭ. Правообладатель банка — ФИПИ, ЕГЭ·ПРО не является его официальным ресурсом."},{"q":"Как проверяются сочинения?","a":"По критериям ЕГЭ: за каждый критерий выставляются баллы и пишется комментарий, что засчитано и где баллы потеряны. Проверку выполняет ИИ, поэтому результат служит ориентиром для подготовки."},{"q":"Спишутся ли деньги повторно?","a":"Нет. Оплата разовая на 30 дней, карта не сохраняется, автопродления нет. Чтобы продолжить занятия, нужна новая оплата."}]$j$::jsonb, updated_at = now()
 where key = 'faq'
   and md5(data::text) = 'feee0014c1e3a31ab31c87ad27ab368f';

update public.content_blocks
   set data = jsonb_set(
         jsonb_set(coalesce(data, '{}'::jsonb), '{pages,home,title}', to_jsonb($j$Тренажёр ЕГЭ с ИИ-репетитором — ЕГЭ·ПРО: задания ФИПИ бесплатно$j$::text), true),
         '{pages,home,description}', to_jsonb($j$ЕГЭ·ПРО — онлайн-тренажёр ЕГЭ с ИИ-репетитором: 51 391 задание из банка ФИПИ по 11 предметам, диагностика, план и проверка сочинений. Начни бесплатно.$j$::text), true),
       updated_at = now()
 where key = 'seo';
